-- Gold Query
SELECT T2.AdmEmail1, T2.School FROM satscores AS T1 INNER JOIN schools AS T2 ON T1.cds = T2.CDSCode ORDER BY T1.NumGE1500 DESC, T1.cds NULLS LAST, T2.cdscode NULLS LAST LIMIT 1;

